// Some portions generated by Co-Pilot
import type { ComponentProps } from "react";
import { afterEach, describe, it, expect, vi } from "vitest";
import { render, screen } from "@testing-library/react";
import NewsCardList from "../index";

// Mock the useLocale hook for EventCard
vi.mock("next-intl", async () => {
  const actual = await vi.importActual<typeof import("next-intl")>("next-intl");
  const messages = (await import("@/../locales/en.json")).default;
  return {
    ...actual,
    useLocale: () => "en",
    useTranslations: (namespace: "ModernPages.news" | "ModernPages.common") =>
      actual.createTranslator({ locale: "en", messages, namespace }),
  };
});

type Post = ComponentProps<typeof NewsCardList>["posts"][number];

const createMockPost = (
  slug: string,
  overrides: Partial<Post["metadata"]> = {},
): Post => ({
  slug,
  year: "2024",
  month: "03",
  metadata: {
    title: "Test Post",
    description: "Test description",
    date: "2024-03-15",
    tags: ["java"],
    ...overrides,
  },
});

afterEach(() => vi.restoreAllMocks());

describe("NewsCardList", () => {
  const defaultProps = {
    posts: [
      createMockPost("post-1", { title: "Post 1" }),
      createMockPost("post-2", { title: "Post 2" }),
      createMockPost("post-3", { title: "Post 3" }),
    ],
    previousPageNumber: null,
    previousPageLink: null,
    nextPage: "",
    currentPage: 1,
    totalPages: 1,
    baseUrl: "/news",
  };

  it("renders all posts without duplicate-key warnings", () => {
    const consoleError = vi.spyOn(console, "error");
    render(<NewsCardList {...defaultProps} />);
    expect(screen.getAllByText("Post 1").length).toBeGreaterThan(0);
    expect(screen.getAllByText("Post 2").length).toBeGreaterThan(0);
    expect(screen.getAllByText("Post 3").length).toBeGreaterThan(0);
    expect(consoleError).not.toHaveBeenCalled();
  });

  it("distinguishes posts that reuse a slug in different months", () => {
    const consoleError = vi.spyOn(console, "error");
    render(
      <NewsCardList
        {...defaultProps}
        posts={[
          createMockPost("shared-slug", { title: "March post" }),
          {
            ...createMockPost("shared-slug", {
              title: "April post",
              date: "2024-04-15",
            }),
            month: "04",
          },
        ]}
      />,
    );
    expect(screen.getByText("March post")).toBeInTheDocument();
    expect(screen.getByText("April post")).toBeInTheDocument();
    expect(consoleError).not.toHaveBeenCalled();
  });

  it("renders the Submit News link", () => {
    render(<NewsCardList {...defaultProps} />);
    const submitLinks = screen.getAllByRole("link", { name: "Submit news" });
    expect(submitLinks.length).toBeGreaterThan(0);
  });

  it("renders with empty posts array", () => {
    render(<NewsCardList {...defaultProps} posts={[]} />);
    const submitLinks = screen.getAllByRole("link", { name: "Submit news" });
    expect(submitLinks.length).toBeGreaterThan(0);
  });

  it("renders the component container", () => {
    const { container } = render(<NewsCardList {...defaultProps} />);
    expect(container.firstChild).toBeInTheDocument();
  });
});
